def para(text: str, cite: str) -> dict:
    return {"text": text, "cite": cite}


def record(title, notes, context, classical, modern, models, critical, research):
    return {
        "title": title,
        "notes": [para(*item) for item in notes],
        "context": [para(*item) for item in context],
        "classical": classical,
        "modern_sources": modern,
        "models": models,
        "critical": [para(*item) for item in critical],
        "research": [para(*item) for item in research],
    }


