def build_entry(verse: int, item: dict) -> dict:
    entry = shared.build_entry(verse, item)
    for field in ("classical", "modern"):
        for source in entry[field]:
            source_id = source.get("sourceId")
            if source_id == "ar_fayd_safi":
                page, group = FAYD_GROUPS[verse]
                source["sourceUrl"] = (
                    "https://www.greattafsirs.com/Tafsir_Library.aspx?FromMainTafsir=1&"
                    f"MadhabNo=4&TafsirNo=41&SoraNo=4&AyahNo={page}&LanguageID=1"
                )
                source["cite"] = (
                    f"فیض کاشانی، ۱۰۹۰ق، *الصافي في تفسير كلام الله الوافي*، شرحِ گروهیِ نساء {group}؛ "
                    "GreatTafsirs، صفحهٔ گروهیِ واقعی؛ چاپ/صفحهٔ کتاب احراز نشده."
                )
                source["evidence"] = f"موضعِ بررسی: شرحِ گروهیِ واقعیِ نساء {group}؛ خلاصه به همان صفحه متصل است."
            elif source_id == "en_tafheem_ul_quran":
                url, group = TAFHEEM_GROUPS[verse]
                source["sourceUrl"] = url
                source["cite"] = (
                    f"مودودی، *تفہيم القرآن*، ذیلِ نساء ۴:{verse}؛ شرحِ گروهیِ واقعیِ {group}؛ "
                    "یادداشت‌های شماره‌دار فقط در مواردِ مربوط ذکر شده‌اند."
                )
                source["evidence"] = f"موضعِ بررسی: صفحهٔ رسمیِ شرحِ گروهیِ {group}؛ ترجمه یا یادداشتِ مربوط به آیه مقابله شده است."
    return entry


def build_catalog(registry: dict) -> dict:
    registry_by_id = {source["id"]: source for source in registry["sources"]}
    source_ids = [
        "ar_tabari_qurancom", "ar_ibn_kathir_qurancom", "ar_jalalayn_qurancom",
        "ar_tusi_tibyan", "ar_fayd_safi", "ar_qe_arabic_moyassar", "en_tafheem_ul_quran",
    ]
    direct_ids = ("ar_tabari_qurancom", "ar_ibn_kathir_qurancom", "ar_jalalayn_qurancom", "ar_tusi_tibyan")
    source_urls = {
        source_id: [shared.SOURCE_META[source_id]["url"].format(verse=verse) for verse in range(73, 85)]
        for source_id in direct_ids
    }
    source_urls["ar_fayd_safi"] = [
        f"https://www.greattafsirs.com/Tafsir_Library.aspx?FromMainTafsir=1&MadhabNo=4&TafsirNo=41&SoraNo=4&AyahNo={page}&LanguageID=1"
        for page in (73, 81, 82)
    ]
    source_urls["ar_qe_arabic_moyassar"] = ["https://quranenc.com/en/browse/arabic_moyassar"]
    source_urls["en_tafheem_ul_quran"] = [url for url, _ in dict.fromkeys(TAFHEEM_GROUPS.values())]
    bases = {
        "ar_tabari_qurancom": "آرشیوِ عربیِ نسخهٔ ۱٫۱ و صفحاتِ آیه‌محورِ Quran.com؛ مقابلهٔ موضعی است و ارزیابیِ کاملِ اسناد ادعا نمی‌شود.",
        "ar_ibn_kathir_qurancom": "آرشیوِ عربیِ نسخهٔ ۱٫۱ و صفحاتِ آیه‌محورِ Quran.com؛ گزارش‌های حدیثی به ابن‌کثیر منسوب‌اند.",
        "ar_jalalayn_qurancom": "دوازده صفحهٔ آیه‌محورِ Quran.com برای نساء ۴:۷۳–۸۴ بررسی شد.",
        "ar_tusi_tibyan": "صفحه‌های مستقیمِ GreatTafsirs برای ۴:۷۳–۸۴ بررسی شد؛ اختلافِ اقوال ثبت شده و چاپ یا صفحهٔ کتاب حدس زده نشده است.",
        "ar_fayd_safi": "سه صفحهٔ گروهیِ واقعیِ GreatTafsirs برای ۴:۷۳–۷۷، ۴:۷۸–۸۱ و ۴:۸۲–۸۵ مقابله شد؛ نقل‌های امامی به مأخذ نسبت داده شدند.",
        "ar_qe_arabic_moyassar": "متنِ محلیِ آیه‌به‌آیهٔ التفسير الميسر در نسخهٔ QuranEnc 1.0.0 برای ۴:۷۳–۸۴ بررسی شد.",
        "en_tafheem_ul_quran": "دو صفحهٔ رسمیِ ۴:۷۱–۷۶ و ۴:۷۷–۸۷ و یادداشت‌های ۱۰۳–۱۱۲ بررسی شدند؛ تعمیم‌های تاریخی به مودودی منسوب‌اند.",
    }
    items = []
    for source_id in source_ids:
        source = registry_by_id[source_id]
        items.append({
            "id": source_id,
            "title": source["title"],
            "author": source["author"],
            "language": source["language"],
            "status": "available" if source.get("localAvailable", False) else "excerpt-only",
            "basis": bases[source_id],
            "sourceUrl": source_urls[source_id][0],
            "sourceUrls": source_urls[source_id],
            "scope": "نساء ۴:۷۳–۸۴",
            "version": source.get("version", "صفحات آیه‌محور/گروهی؛ چاپ و صفحهٔ کتاب احراز نشده"),
            "tradition": source.get("tradition", shared.SOURCE_TRADITIONS[source_id]),
        })
    return {
        "id": COLLECTION_ID,
        "title": "منابعِ تفسیریِ مورد استناد در بستهٔ نساء ۴:۷۳–۸۴",
        "status": "mixed-linked-and-summary-only",
        "items": items,
        "comparativeCore": {
            "scope": "هر آیهٔ نساء ۴:۷۳–۸۴",
            "sunniSourceIds": sorted(SUNNI_CORE),
            "shiaSourceIds": sorted(SHIA_CORE),
            "note": (
                "در هر آیه سه شرحِ اهل‌سنت و دو شرحِ امامیه با خلاصهٔ منتسب و پیوندِ مستقیم یا گروهیِ دامنه‌مشخص آمده‌اند؛ "
                "دو شرحِ معاصر و سه کاربستِ مستقلِ ایزوتسو، فیلمور و معناشناسیِ شناختی نیز ثبت شده‌اند. "
                "تطبیق‌های رواییِ فیض، اختلافِ اقوالِ طوسی و خوانش‌های معاصرِ مودودی به منابعِ خود نسبت داده شده‌اند."
            ),
        },
        "notice": (
            "خلاصه‌ها نقلِ لفظی نیستند؛ اطلاعاتِ نشر یا صفحهٔ احرازنشده ساخته نشده و مقابلهٔ کاملِ همهٔ اسانید ادعا نمی‌شود. "
            "اختلافِ تفسیرهای تاریخی و روایی حفظ شده و پیش‌نویس‌ها نیازمندِ داوریِ تخصصی‌اند."
        ),
    }


def main() -> None:
    registry = json.loads(REGISTRY_PATH.read_text(encoding="utf-8"))
    dossier = json.loads(DOSSIER_PATH.read_text(encoding="utf-8"))
    for verse, item in DATA.items():
        if not any("فولادوند/Tanzil" in note["cite"] for note in item["notes"]):
            item["notes"][0]["cite"] += f"؛ متنِ قرآن و ترجمهٔ فولادوند/Tanzil، نساء ۴:{verse}."
        dossier["verses"][f"4:{verse}"] = build_entry(verse, item)

    dossier["batches"] = [batch for batch in dossier["batches"] if batch["id"] != BATCH_ID]
    nisa_end, nisa_gap = shared.nisa_coverage(dossier["verses"])
    end_fa = str(nisa_end).translate(str.maketrans("0123456789", "۰۱۲۳۴۵۶۷۸۹"))
    dossier["batches"].append({
        "id": BATCH_ID,
        "title": "بستهٔ سی‌وهشتم: نساء ۴:۷۳–۸۴؛ مسئولیت، حمایت و خبر",
        "range": "4:73–84",
        "count": 12,
        "status": (
            "۱۲ پروندهٔ آیه‌محور با دست‌کم پنج بندِ مستند در هر یک از شش فیلد؛ "
            "در هر آیه پنج تفسیرِ کهن (سه اهل‌سنت و دو امامیه)، دو شرحِ معاصر و سه کاربستِ معناشناختی آمده است؛ "
            f"پیش‌نویسِ نیازمندِ بازبینیِ تخصصی؛ {nisa_gap}."
        ),
    })
    dossier["batches"].sort(key=lambda batch: int(batch["id"].split("-")[1]))
    for batch in dossier["batches"]:
        if batch.get("range", "").startswith("4:") and "؛ نساء ۴:" in batch.get("status", ""):
            prefix = batch["status"].split("؛ نساء ۴:", 1)[0]
            batch["status"] = f"{prefix}؛ {nisa_gap}."
    dossier["notice"] = (
        "این پرونده‌ها پیش‌نویس‌های تحریریِ منبع‌محورند و بازبینیِ تخصصی را پشت سر نگذاشته‌اند. "
        f"نساء در این checkout بازهٔ ۴:۱–{end_fa} را پوشش می‌دهد؛ {nisa_gap}. "
        "بسته‌های یونس بازه‌های ۱۰:۴۹–۶۰، ۱۰:۶۱–۷۲ و ۱۰:۷۳–۸۴ را پوشش می‌دهند؛ برای ۱۰:۱–۴۸ پرونده‌ای ساخته نشده است. "
        "این داده‌ها ادعای تکمیلِ هیچ‌یک از دو سوره یا کل قرآن را نمی‌کنند. خلاصه‌ها نقلِ لفظی نیستند؛ اختلافِ اقوال و دامنهٔ واقعیِ صفحاتِ گروهی جدا ثبت شده و هیچ بند بازبینیِ تخصصی‌شده معرفی نمی‌شود."
    )

    method = dossier["editorialMethod"]
    method = re.sub(r"نساء ۴:\d+–۱۷۶ هنوز(?: در این checkout)? پوشش ندارد", nisa_gap, method)
    addition = (
        " در بستهٔ نساء ۴:۷۳–۸۴، اختلافِ نحوی و رواییِ تمنای غنیمت در ۴:۷۳، دو فرجامِ قتل و غلبه در ۴:۷۴، "
        "زمینهٔ حمایت از مستضعفان و تطبیقِ امامی در ۴:۷۵، چند معنای طاغوت در ۴:۷۶، و روایت‌های متفاوتِ ۴:۷۷ جدا نگه داشته شده‌اند. "
        "در ۴:۷۸–۷۹ تفاوتِ نسبتِ جمعیِ رخدادها با مسئولیتِ فردی و اختلافِ مصداقِ حسنه و سیئه حفظ شده است؛ "
        "خوانشِ امامیِ فیض دربارهٔ اولی‌الامر در ۴:۸۳ از اقوالِ فرماندهان و عالمان تفکیک شده است. "
        "صفحه‌های رسمیِ تفهيم برای ۴:۷۱–۷۶ و ۴:۷۷–۸۷، یادداشت‌های ۱۰۳–۱۱۲، صفحاتِ مستقیمِ طوسی و جلالین، "
        "و صفحه‌های گروهیِ فیض برای ۴:۷۳–۷۷، ۴:۷۸–۸۱ و ۴:۸۲–۸۵ مقابله شدند؛ چاپ یا صفحهٔ احرازنشده ساخته نشده است. "
        f"این دوازده پرونده پیش‌نویس و نیازمندِ بازبینیِ تخصصی‌اند؛ {nisa_gap}."
    )
    if "در بستهٔ نساء ۴:۷۳–۸۴" not in method:
        method += addition
    dossier["editorialMethod"] = method
    DOSSIER_PATH.write_text(json.dumps(dossier, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    catalog = json.loads(CATALOG_PATH.read_text(encoding="utf-8"))
    catalog["collections"] = [collection for collection in catalog["collections"] if collection["id"] != COLLECTION_ID]
    catalog["collections"].append(build_catalog(registry))
    catalog["version"] = max(int(catalog.get("version", 0)), 14)
    CATALOG_PATH.write_text(json.dumps(catalog, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Added {len(DATA)} dossiers; total={len(dossier['verses'])}; batch=4:73–84")


if __name__ == "__main__":
    main()
